    List<Fit> sorted = new ArrayList<>(List.of(fits));
    sorted.sort(Comparator.comparingDouble(Fit::minWidth));
    WritableSignal<Integer> fitIndex = Signals.signal(0);
    return new FitSlot(sorted, fitIndex);
}

