#!/usr/bin/env python3
import re
import sys
from pathlib import Path

CHILDREN = ".children("
STF = "SizeThatFits.make("


def scan_code(s):
    """Yield (i, ch) for characters outside strings/comments."""
    i = 0
    n = len(s)
    state = "code"  # code | line | block | string | char
    while i < n:
        c = s[i]
        if state == "code":
            if c == "/" and i + 1 < n and s[i + 1] == "/":
                state = "line"
                i += 2
                continue
            if c == "/" and i + 1 < n and s[i + 1] == "*":
                state = "block"
                i += 2
                continue
            if c == '"':
                state = "string"
                i += 1
                continue
            if c == "'":
                state = "char"
                i += 1
                continue
            yield i, c
            i += 1
        elif state == "line":
            if c == "\n":
                state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and s[i + 1] == "/":
                state = "code"
                i += 2
            else:
                i += 1
        elif state == "string":
            if c == "\\":
                i += 2
            elif c == '"':
                state = "code"
                i += 1
            else:
                i += 1
        elif state == "char":
            if c == "\\":
                i += 2
            elif c == "'":
                state = "code"
                i += 1
            else:
                i += 1


def find_marker(s, marker):
    out = []
    for i, _ in scan_code(s):
        if s.startswith(marker, i):
            out.append(i)
    return out


