    @Test
    void blockChildrenEmitIdenticalOpcodesToVarargs() {
        FrameOpcodeSink varargsSink = new FrameOpcodeSink();
        new Emitter(varargsSink).mount(
                VStack.make(v -> v.spacing(8)).children(childScope -> {
                    childScope.add(Text.make("a").modifiers(fontSize(18), FontWeight.BOLD));
                    childScope.add(HStack.make(h -> h.spacing(4)).children(childScope1 -> {
                            childScope1.add(Text.make("b"));
                            childScope1.add(Spacer.make());
                        }));
                }),
                Environment.DEFAULT);

        FrameOpcodeSink blockSink = new FrameOpcodeSink();
        new Emitter(blockSink).mount(
                VStack.make(v -> v.spacing(8)).children(root -> {
                    root.add(Text.make("a").modifiers(fontSize(18), FontWeight.BOLD));
                    root.add(HStack.make(h -> h.spacing(4)).children(row -> {
                        row.add(Text.make("b"));
                        row.add(Spacer.make());
                    }));
                }),
                Environment.DEFAULT);

        assertEquals(varargsSink.frame().opcodes(), blockSink.frame().opcodes());
        assertArrayEquals(varargsSink.frame().strings(), blockSink.frame().strings());
    }
}

