         ProtocolFrame refill = sink.frame();
         assertEquals(1, countOps(refill, Categories.TREE, Commands.Tree.CREATE_NODE));
         assertEquals(1, countOps(refill, Categories.TREE, Commands.Tree.INSERT_CHILD));
